<?php
require_once '../includes/auth.php'; requireActiveUser(); requireTenantContext(); requireModulePermission('payments','create');
global $conn;$tid=(int)getCurrentTenantId();$errors=[];$cols=[];$r=$conn->query("SHOW COLUMNS FROM payments");if($r)while($x=$r->fetch_assoc())$cols[]=$x['Field'];
$invoices=[];$q=$conn->prepare("SELECT * FROM invoices WHERE tenant_id=? ORDER BY id DESC LIMIT 300");if($q){$q->bind_param('i',$tid);$q->execute();$z=$q->get_result();while($x=$z->fetch_assoc())$invoices[]=$x;$q->close();}
$v=['invoice_id'=>'','amount'=>'','payment_method'=>'cash','payment_date'=>date('Y-m-d'),'reference'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();foreach($v as $k=>$d)$v[$k]=trim((string)($_POST[$k]??$d));$iid=(int)$v['invoice_id'];$amount=(float)$v['amount'];if(!$iid||$amount<=0)$errors[]='Invoice and positive payment amount are required.';if(!$errors){$q=$conn->prepare("SELECT * FROM invoices WHERE id=? AND tenant_id=? LIMIT 1");$q->bind_param('ii',$iid,$tid);$q->execute();$invoice=$q->get_result()->fetch_assoc();$q->close();if(!$invoice)$errors[]='Invoice not found.';else{$fields=[];$vals=[];$types='';foreach(['invoice_id','amount','payment_method','payment_date','reference'] as $f)if(in_array($f,$cols,true)){$fields[]=$f;$vals[]=$f==='invoice_id'?$iid:($f==='amount'?$amount:$v[$f]);$types.=$f==='invoice_id'?'i':($f==='amount'?'d':'s');}if(in_array('tenant_id',$cols,true)){array_unshift($fields,'tenant_id');array_unshift($vals,$tid);$types='i'.$types;}if(in_array('payment_number',$cols,true)){array_splice($fields,1,0,'payment_number');array_splice($vals,1,0,'PAY-'.date('YmdHis').'-'.random_int(100,999));$types='is'.$types[1].substr($types,2);}if($fields){$q=$conn->prepare("INSERT INTO payments(".implode(',',$fields).") VALUES(".implode(',',array_fill(0,count($fields),'?')).")");$q->bind_param($types,...$vals);if($q->execute())redirect('../payments/index.php');$errors[]=$q->error;$q->close();}}}}
require_once '../includes/header.php';require_once '../includes/sidebar.php';?><div class="main-content"><div class="page-header"><div><h1>Record Payment</h1><p>Record a tenant-scoped customer payment.</p></div></div><div class="card" style="padding:20px"><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><form method="post"><?=csrfField()?><div class="form-grid"><label>Invoice *<select name="invoice_id" required><option value="">Select invoice</option><?php foreach($invoices as $x):?><option value="<?=$x['id']?>" <?=$v['invoice_id']==$x['id']?'selected':''?>><?=e($x['invoice_number']??$x['id'])?> — <?=e(formatMoney($x['total_amount']??$x['amount']??0))?></option><?php endforeach;?></select></label><label>Amount *<input type="number" name="amount" step="0.01" min="0.01" value="<?=e($v['amount'])?>" required></label><label>Payment Method<select name="payment_method"><option>cash</option><option>mpesa</option><option>bank</option><option>card</option></select></label><label>Date<input type="date" name="payment_date" value="<?=e($v['payment_date'])?>"></label><label>Reference<input name="reference" value="<?=e($v['reference'])?>"></label></div><button class="btn btn-primary">Save Payment</button></form></div></div><?php require_once '../includes/footer.php';?>